from m8c import PREP
SUBS.append(PREP)

# 모의 면접 개편 (RYU 2026-11-24): 기존 모의 면접 묶음은 자기소개·경험(면접 흐름)과 예상 질문·기출(질문 모음)로 옮기고,
# 맨 뒤 소분류 "모의 면접"은 분야별 무작위 한 문제 연습(m8d.MOCK)으로 바꿉니다.
_old = next(s for s in SUBS if s["n"] == "모의 면접")
SUBS.remove(_old)
SUBS[0]["b"].append(next(b for b in _old["b"] if b["t"] == "모의 면접과 마무리 질문"))
PREP["b"].append(next(b for b in _old["b"] if b["t"] == "면접 질문 모음"))
from m8d import MOCK
SUBS.append(MOCK)

# 소분류를 모의 면접 분야에 맞춤 (RYU 2026-11-24): 자기소개·지원 동기 | 강점·약점·경험 | 희망 부서별 면접 | 상황 대처 | 면접 흐름·마무리 | 예상 질문·기출 | 모의 면접
_s1 = SUBS[0]["b"]
_intro = next(b for b in _s1 if b["t"] == "자기소개와 지원 동기")
_str = next(b for b in _s1 if b["t"] == "강점·약점·경험")
_flow = next(b for b in _s1 if b["t"] == "모의 면접과 마무리 질문")
_bank = PREP["b"].pop()          # 면접 질문 모음 (added above)
SUBS[:] = [{"n": "자기소개·지원 동기", "b": [_intro]}, {"n": "강점·약점·경험", "b": [_str]}, SUBS[1], SUBS[2],
           {"n": "면접 흐름·마무리", "b": [_flow, _bank]}, PREP, MOCK]
